<script setup>
import {computed,onMounted,ref} from 'vue';import SiteHeader from '../components/SiteHeader.vue';import SiteFooter from '../components/SiteFooter.vue';import FeeBreakdown from '../components/FeeBreakdown.vue';import {getCollegeContent,submitApplication} from '../services/api';
const data=ref({site:{},programs:[]}),form=ref({program_id:'',first_name:'',last_name:'',date_of_birth:'',gender:'',email:'',phone:'',national_id:'',address:'',city:'',country:'Pakistan',highest_qualification:'',institution:'',graduation_year:'',grade_percentage:'',statement:'',transcript:null,identity_document:null,confirmation:false}),errors=ref({}),busy=ref(false),reference=ref('');const selectedProgram=computed(()=>data.value.programs.find(program=>String(program.id)===String(form.value.program_id)));
onMounted(async()=>{try{data.value=(await getCollegeContent()).data.data}catch{}document.title=`Online Application | ${data.value.site.college_name||'College of Nursing'}`});
function file(field,event){form.value[field]=event.target.files?.[0]||null}
async function submit(){busy.value=true;errors.value={};try{const body=new FormData();Object.entries(form.value).forEach(([k,v])=>{if(v!==null&&v!=='')body.append(k,typeof v==='boolean'?(v?'1':'0'):v)});reference.value=(await submitApplication(body)).data.data.reference;window.scrollTo({top:0,behavior:'smooth'})}catch(e){errors.value=e.response?.data?.errors||{form:[e.response?.data?.message||'Your application could not be submitted.']};document.querySelector('.is-invalid')?.scrollIntoView({behavior:'smooth',block:'center'})}finally{busy.value=false}}
</script>
<template><SiteHeader :site="data.site"/><main><section class="apply-hero"><div class="container"><span class="eyebrow text-info">ONLINE ADMISSIONS</span><h1>Apply to {{data.site.college_name||'Our College'}}</h1><p>Complete the application below. Your information and documents are securely submitted to {{data.site.college_name||'our college'}} admissions team.</p></div></section><section class="section application-bg"><div class="container"><div v-if="reference" class="application-success"><i class="bi bi-check-circle-fill"></i><h2>Application Submitted</h2><p>Your application to {{data.site.college_name||'the college'}} has been received. Save your reference number for future communication.</p><strong>{{reference}}</strong><div><router-link to="/" class="btn btn-primary">Return to Home</router-link></div></div><form v-else class="online-application" @submit.prevent="submit" novalidate><div v-if="errors.form" class="alert alert-danger">{{errors.form[0]}}</div><div class="application-intro"><div><h2>{{data.site.college_name||'College'}} Online Application</h2><p>Fields marked with * are required.</p></div><span><i class="bi bi-shield-check"></i> Secure submission</span></div>
<fieldset><legend><b>1</b> Program Selection</legend><div class="row"><div class="col-lg-8"><label for="program">Program *</label><select id="program" v-model="form.program_id" class="form-select" :class="{'is-invalid':errors.program_id}" required><option value="" disabled>Select the program you want to apply for</option><option v-for="p in data.programs" :key="p.id" :value="p.id">{{p.name}} — {{p.duration}}</option></select><div class="invalid-feedback">{{errors.program_id?.[0]}}</div><FeeBreakdown v-if="selectedProgram" :fees="selectedProgram.fees"/></div></div></fieldset>
<fieldset><legend><b>2</b> Personal Information</legend><div class="row g-3"><div class="col-md-6" v-for="f in [['first_name','First name *'],['last_name','Last name *'],['date_of_birth','Date of birth *','date'],['email','Email address *','email'],['phone','Phone number *','tel'],['national_id','National ID / Passport']]" :key="f[0]"><label :for="f[0]">{{f[1]}}</label><input :id="f[0]" v-model="form[f[0]]" :type="f[2]||'text'" class="form-control" :class="{'is-invalid':errors[f[0]]}"><div class="invalid-feedback">{{errors[f[0]]?.[0]}}</div></div><div class="col-md-6"><label for="gender">Gender *</label><select id="gender" v-model="form.gender" class="form-select" :class="{'is-invalid':errors.gender}"><option value="" disabled>Select</option><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option><option value="prefer_not_to_say">Prefer not to say</option></select><div class="invalid-feedback">{{errors.gender?.[0]}}</div></div><div class="col-12"><label for="address">Address *</label><textarea id="address" v-model="form.address" class="form-control" :class="{'is-invalid':errors.address}" rows="3"/><div class="invalid-feedback">{{errors.address?.[0]}}</div></div><div class="col-md-6"><label for="city">City *</label><input id="city" v-model="form.city" class="form-control" :class="{'is-invalid':errors.city}"><div class="invalid-feedback">{{errors.city?.[0]}}</div></div><div class="col-md-6"><label for="country">Country *</label><input id="country" v-model="form.country" class="form-control" :class="{'is-invalid':errors.country}"><div class="invalid-feedback">{{errors.country?.[0]}}</div></div></div></fieldset>
<fieldset><legend><b>3</b> Education</legend><div class="row g-3"><div class="col-md-6"><label>Highest qualification *</label><input v-model="form.highest_qualification" class="form-control" :class="{'is-invalid':errors.highest_qualification}"><div class="invalid-feedback">{{errors.highest_qualification?.[0]}}</div></div><div class="col-md-6"><label>Institution *</label><input v-model="form.institution" class="form-control" :class="{'is-invalid':errors.institution}"><div class="invalid-feedback">{{errors.institution?.[0]}}</div></div><div class="col-md-6"><label>Graduation year *</label><input v-model="form.graduation_year" type="number" class="form-control" :class="{'is-invalid':errors.graduation_year}"><div class="invalid-feedback">{{errors.graduation_year?.[0]}}</div></div><div class="col-md-6"><label>Grade percentage</label><input v-model="form.grade_percentage" type="number" step="0.01" min="0" max="100" class="form-control" :class="{'is-invalid':errors.grade_percentage}"><div class="invalid-feedback">{{errors.grade_percentage?.[0]}}</div></div><div class="col-12"><label>Personal statement</label><textarea v-model="form.statement" class="form-control" rows="5" placeholder="Tell us why you want to pursue nursing (maximum 3,000 characters)."/></div></div></fieldset>
<fieldset><legend><b>4</b> Supporting Documents</legend><p class="upload-help">Upload PDF, JPG or PNG files. Maximum 5 MB each.</p><div class="row g-3"><div class="col-md-6"><label for="transcript">Academic transcript *</label><input id="transcript" type="file" accept=".pdf,.jpg,.jpeg,.png" class="form-control" :class="{'is-invalid':errors.transcript}" @change="file('transcript',$event)"><div class="invalid-feedback">{{errors.transcript?.[0]}}</div></div><div class="col-md-6"><label for="identity">ID or passport document *</label><input id="identity" type="file" accept=".pdf,.jpg,.jpeg,.png" class="form-control" :class="{'is-invalid':errors.identity_document}" @change="file('identity_document',$event)"><div class="invalid-feedback">{{errors.identity_document?.[0]}}</div></div></div></fieldset>
<div class="application-confirm"><label class="form-check"><input v-model="form.confirmation" type="checkbox" class="form-check-input" :class="{'is-invalid':errors.confirmation}"> I confirm that the information provided is accurate and I authorize the college to review my application. *</label><div v-if="errors.confirmation" class="text-danger small">{{errors.confirmation[0]}}</div></div><button class="btn btn-primary btn-lg" :disabled="busy"><span v-if="busy" class="spinner-border spinner-border-sm me-2"></span>{{busy?'Submitting Application…':'Submit Application'}} <i v-if="!busy" class="bi bi-arrow-right"></i></button></form></div></section></main><SiteFooter :site="data.site"/></template>
